"""FastAPI dependency providers.The API is a strictly read-only projection of state the orchestrator alreadyowns. Dependencies therefore resolve *existing* singletons off ``app.state``and never construct anything: a second ``InMemoryStateStore`` created by arequest handler would be permanently empty, and the endpoint would report anempty account list while the engine traded normally.Every provider fails with 503 rather than ``AttributeError`` when thecomposition root has not wired the object. A missing dependency is anoperational state ("not ready"), not a bug in the request."""from __future__ import annotationsfrom typing import Annotated, Final, TypeVarimport structlogfrom fastapi import Depends, HTTPException, Request, WebSocket, statusfrom betdoc.adapters.cache.state_store import InMemoryStateStorefrom betdoc.presentation.api.broadcaster import WebsocketBroadcaster__all__ = [    "BroadcasterDep",    "ProfileIdDep",    "StateStoreDep",    "get_broadcaster",    "get_broadcaster_from_websocket",    "get_profile_id",    "get_state_store",    "get_state_store_from_websocket",]_log: Final[structlog.stdlib.BoundLogger] = structlog.get_logger(    component="presentation.api.dependencies")_DEFAULT_PROFILE_ID: Final[str] = "primary"T = TypeVar("T")def _require(state_holder: object, attribute: str, expected: type[T]) -> T:    """Fetch a wired singleton off ``app.state`` or fail with 503.    Type-checks the retrieved object. A mis-wired composition root that stored    the wrong instance would otherwise surface as a confusing ``AttributeError``    deep inside a handler instead of a clear startup-order fault.    """    value = getattr(state_holder, attribute, None)    if value is None:        _log.error("dependencies.not_wired", attribute=attribute)        raise HTTPException(            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,            detail=f"{attribute} is not available; the service is still starting",        )    if not isinstance(value, expected):        _log.error(            "dependencies.wrong_type",            attribute=attribute,            expected=expected.__name__,            actual=type(value).__name__,        )        raise HTTPException(            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,            detail=f"{attribute} is misconfigured",        )    return valuedef get_state_store(request: Request) -> InMemoryStateStore:    """The live L1 cache the orchestrator reads from.    Returns the *same* instance the refresh daemon writes to, so the API can    never disagree with the engine about balances or exposure.    """    return _require(request.app.state, "store", InMemoryStateStore)def get_state_store_from_websocket(websocket: WebSocket) -> InMemoryStateStore:    """WebSocket variant. ``WebSocket`` has no ``Request`` to depend on."""    return _require(websocket.app.state, "store", InMemoryStateStore)def get_broadcaster(request: Request) -> WebsocketBroadcaster:    return _require(request.app.state, "broadcaster", WebsocketBroadcaster)def get_broadcaster_from_websocket(websocket: WebSocket) -> WebsocketBroadcaster:    return _require(websocket.app.state, "broadcaster", WebsocketBroadcaster)def get_profile_id(request: Request) -> str:    """Active profile id, from ``app.state`` with a documented fallback.    Single-operator today, so a constant is honest. When multi-tenancy arrives    this becomes the authenticated subject and every caller already reads it    through this one function.    """    configured = getattr(request.app.state, "profile_id", None)    return configured if isinstance(configured, str) and configured else _DEFAULT_PROFILE_IDStateStoreDep = Annotated[InMemoryStateStore, Depends(get_state_store)]BroadcasterDep = Annotated[WebsocketBroadcaster, Depends(get_broadcaster)]ProfileIdDep = Annotated[str, Depends(get_profile_id)]